// kesfetData.ts'den ayrıldı (SRP, 03.10) — içerik değişmedi, bayt-duyarlı taşıma
// ════════════════════════════════════════════════════════
// ── 22: SURE BİLGİLERİ (01.10: 25 sureye çıkarıldı; aciklama = akordeon açılınca görünen uzun anlatım) ──
export interface SureBilgi {
  n: number; ad: string; inis: string; konu: string; fazilet: string; aciklama?: string; nuzul?: string;
  konu_en?: string; konu_ar?: string; konu_id?: string; konu_ur?: string;
  aciklama_en?: string; aciklama_ar?: string; aciklama_id?: string; aciklama_ur?: string;
  fazilet_en?: string; fazilet_ar?: string; fazilet_id?: string; fazilet_ur?: string;
  nuzul_en?: string; nuzul_ar?: string; nuzul_id?: string; nuzul_ur?: string;
}
export const SURE_BİLGİLERİ: SureBilgi[] = [
  { n: 1, ad: "Fâtiha", inis: "Mekke", konu: "Kur'an'ın özeti ve duanın atası — hamd, kulluk ve hidayet istemi.", fazilet: "Her rekatta okunur; 'saptırmayan ve sapmayan yol' diye en kısa dua buradadır.", aciklama: "Kur'an'ın ilk suresi ve namazın her rekatında zorunlu olarak okunan tek sure; yedi ayeti olduğu için 'Seb'ul-Mesânî' (yedi defa okunan) adıyla da anılır. Önce Allah hamd ile tanıtılır: Rahmân, Rahîm, kıyamet gününün sahibi. Ardından kul söz alır: 'Yalnız sana kulluk ederiz, yalnız senden yardım isteriz' ve yolunu ister: 'Bizi dosdoğru yola ilet.' Bu yüzden sureye 'Ümmü'l-Kitâb' (kitabın özü) ve 'es-Salât' denir; kul ile Rabbinin arasındaki en kısa ve en dolu konuşma buradadır.", nuzul: "Fâtiha’nın inişi hakkında Mekke ve Medine rivayetleri bulunur; Kur’an tefsiri ve namaz literatüründe Mekke dönemine bağlanması yaygındır. Sure, kulluğun özünü toplar: hamd, yalnız Allah’a ibadet ve yardım dileme, doğru yol talebi. Her namaz rekatında okunması (Buhârî, Ezan; Müslim, Salât rivayet çerçevesi), nüzul bağlamını bireysel ibadetle birleştiren en güçlü uygulamadır. Özel bir sebep-i nüzul iddiası yerine, sureyi açılış duası ve hidayet talebi olarak okumak daha güvenlidir.", nuzul_en: "The revelation timing of al-Fatiha is discussed with both Meccan and Medinan reports; Qur’anic and prayer literature commonly associate it with the Meccan period. The surah gathers the essence of worship: praise, devotion to Allah alone, seeking help, and asking for guidance. Its recitation in every prayer unit connects its context to daily worship. Rather than asserting a single specific occasion of revelation, it is safest to read it as an opening supplication for guidance.", nuzul_ar: "يُذكر في نزول الفاتحة أقوال بينها مكي ومدني، والأشهر في سياق العبادة والقرآن ربطها بالمكي. وتجمع جوهر العبادة: الحمد، وإخلاص العبادة والاستعانة لله، وسؤال الهداية. وقراءتها في كل ركعة تربط معناها بالعبادة اليومية. والأولى قراءتها دعاء افتتاح وهداية دون الجزم بسبب نزول واحد خاص.", nuzul_id: "Waktu turunnya al-Fatihah dibahas dengan riwayat Mekah dan Madinah; literatur Qur’an dan salat umumnya mengaitkannya dengan periode Mekah. Surah ini merangkum inti ibadah: pujian, pengabdian hanya kepada Allah, memohon pertolongan, dan meminta petunjuk. Membacanya di setiap rakaat menghubungkan maknanya dengan ibadah harian. Lebih aman membacanya sebagai doa pembuka dan permohonan hidayah daripada menetapkan satu sebab turun khusus.", nuzul_ur: "فاتحہ کے نزول کے بارے میں مکی اور مدنی روایات مذکور ہیں؛ قرآنی و نمازی ادب میں اسے اکثر مکی دور سے جوڑا جاتا ہے۔ یہ سورت عبادت کا خلاصہ ہے: حمد، خالص بندگی و استعانت، اور ہدایت کی دعا۔ ہر رکعت میں اس کی تلاوت اس کے مفہوم کو روزمرہ عبادت سے جوڑتی ہے۔ ایک مخصوص سبب نزول پر جزم کے بجائے اسے افتتاحی دعا اور ہدایت کی طلب کے طور پر پڑھنا زیادہ محفوظ ہے۔" },
  { n: 2, ad: "Bakara", inis: "Medine", konu: "Mümin, kâfir ve münafığın tarifi; teşri (hükümler) ve İsrâiloğulları kıssası.", fazilet: "Son iki ayet okunursa o geceye yeter; Ayete'l-Kürsî koruma duasıdır. Evde bulundurulmasına dair müjdeler rivayet edilmiştir.", aciklama: "Kur'an'ın en uzun suresi: 286 ayet, yaklaşık iki buçuk cüz. Medine'de inmiştir; oruç, hac, borç, miras, evlilik ve kısas gibi toplumsal hükümlerin büyük bölümü burada konur. Âdem'in yaratılışı, İsrâiloğulları'nın imtihan tarihi ve İbrahim'in Kâbe'yi yükseltişi anlatılır. Kalbi Ayete'l-Kürsî'dir: Allah'ın birliğini, ilmini ve kudretini hiçbir benzetmeye kaçmadan beyan eder. Sure, 'işittik ve itaat ettik; affet bizi, ey Rabbimiz' duasıyla biter — imanın hem akıl hem itaat olduğunun özeti.", nuzul: "Bakara büyük ölçüde Medine döneminde nazil olmuştur. Medine’de Müslüman toplumu devletleşme, komşuluk, ahitler, savaş ve sosyal hukuk meseleleriyle karşılaştı; bu nedenle kıble (2:142-150), oruç (2:183-187), hac, infak, borç/alacak (2:282), faiz yasağı ve aile hükümleri gibi konular ayrıntılı işler. Yahudi ve münafık çevrelerle tartışmalar, geçmiş ümmet kıssaları ve imtihan dersleri bu bağlamda okunur. Son iki ayetin fazileti sahih rivayetlerde geçer (Buhârî, Fedâilü’l-Kur’ân; Müslim, Salâtü’l-Müsâfirîn).", nuzul_en: "Al-Baqarah was largely revealed in the Madinan period. The Muslim community in Medina faced state-building, covenants, conflict, and social law; thus topics such as the qiblah (2:142–150), fasting (2:183–187), pilgrimage, charity, debt contracts (2:282), prohibition of usury, and family rulings are treated in detail. Debates with some Jewish and hypocritical circles and lessons from earlier communities fit this context. The virtue of its last two verses is reported in authentic narrations.", nuzul_ar: "نزلت البقرة في الغالب بالمدينة. واجه المجتمع المسلم هناك بناء الدولة والمواثيق والنزاع والتنظيم الاجتماعي، لذلك تناولت القبلة (2:142-150) والصيام (2:183-187) والحج والإنفاق والدَين (2:282) وتحريم الربا وأحكام الأسرة. وتُفهم مناظرات بعض أهل الكتاب والمنافقين وقصص الأمم السابقة في هذا السياق. وفضل الآيتين الأخيرتين وارد في أحاديث صحيحة.", nuzul_id: "Al-Baqarah sebagian besar turun di periode Madinah. Komunitas Muslim di Madinah menghadapi pembinaan masyarakat, perjanjian, konflik, dan hukum sosial; karena itu kiblat (2:142–150), puasa (2:183–187), haji, infak, utang-piutang (2:282), larangan riba, dan hukum keluarga dibahas rinci. Perdebatan dengan sebagian Ahli Kitab dan munafik serta pelajaran umat terdahulu dipahami dalam konteks ini. Keutamaan dua ayat terakhir diriwayatkan dalam hadis sahih.", nuzul_ur: "سورۃ بقرہ زیادہ تر مدنی دور میں نازل ہوئی۔ مدینہ میں مسلم معاشرے کو تنظیم، عہد و پیمان، اختلافات اور سماجی قوانین کے مسائل درپیش تھے؛ اس لیے قبلہ (2:142–150)، روزہ (2:183–187)، حج، انفاق، قرض/تحریر (2:282)، سود کی ممانعت اور خاندانی احکام تفصیل سے آئے۔ اہلِ کتاب و منافقین سے مباحث اور سابق امتوں کے واقعات اسی پس منظر میں سمجھے جاتے ہیں۔ آخری دو آیات کی فضیلت صحیح روایات میں مذکور ہے۔" },
  { n: 12, ad: "Yûsuf", inis: "Mekke", konu: "Tek bir kıssayı baştan sona anlatan tek sure: Yûsuf'un sabır ve yükseliş destanı.", fazilet: "Kederli ve sabır imtihanı yaşayanların okuması önerilir; kıyamette güzellik verildiği yönünde rivayet meşhurdur.", aciklama: "Kur'an'da tek bir peygamberin hayatını baştan sona anlatan tek suredir. Kardeşlerinin kıskançlığıyla kuyuya atılan Yûsuf; kölelik, iftira ve zindana düşer — ama her seferinde Allah'a güvenir ve her kapıyı açan onun sadakatidir. Sonunda Mısır'ın hazinesini yönetir, kardeşlerini affeder: 'Bugün size kınama yoktur.' Sure, Mekke'nin en zor yılında, Peygamber'in (s.a.v.) yalnızlaştığı günlerde inmiş; 'sabredenin sonu güzeldir' müjdesini bütün müminlere vermiştir.", nuzul: "Yûsuf suresi Mekke döneminde nazil olmuştur. Rivayetlerde müşriklerin, Yahudi bilginlere danışarak Hz. Peygamber’e Yakub ailesinin Mısır’a geliş hikâyesini sormaları ve surenin bu soruya vahiy cevabı olması bağlamı aktarılır (Tirmizî ve tefsir kaynaklarında geçer; ayrıntılar rivayetlere göre değişebilir). Metnin özü, bu kıssayı ‘ahsenü’l-kasas’ olarak sunması ve sabır, iffet, tevbe, af ile kader-tevekkül dengesini öğretmesidir.", nuzul_en: "Surah Yusuf was revealed in the Meccan period. Reports mention that some opponents asked the Prophet about the story of Jacob’s family going to Egypt, and the surah came as a revealed response; details vary across reports. Its core is presenting the story as the best narrative and teaching patience, chastity, repentance, forgiveness, and trust in God’s decree.", nuzul_ar: "نزلت سورة يوسف في العهد المكي. وتذكر روايات أن سؤالاً ورد عن قصة يعقوب وأهله ودخولهم مصر فجاءت السورة جوابًا؛ وتختلف تفاصيل الروايات. وجوهر السورة عرض القصة أحسن القصص وتعليم الصبر والعفة والتوبة والعفو والتوكل.", nuzul_id: "Surah Yusuf turun pada periode Mekah. Riwayat menyebut adanya pertanyaan tentang kisah keluarga Ya‘qub ke Mesir dan surah ini datang sebagai jawaban wahyu; rincian riwayat bisa berbeda. Intinya adalah menyajikan kisah terbaik serta mengajarkan sabar, iffah, tobat, pemaafan, dan tawakal.", nuzul_ur: "سورۃ یوسف مکی دور میں نازل ہوئی۔ روایات میں ہے کہ حضرت یعقوب کے خاندان کے مصر جانے کے واقعے کے بارے میں سوال ہوا اور یہ سورت وحی کے جواب کے طور پر نازل ہوئی؛ تفصیلات مختلف ہو سکتی ہیں۔ اصل پیام صبر، عفت، توبہ، درگزر اور تقدیر پر بھروسے کی تعلیم ہے۔" },
  { n: 18, ad: "Kehf", inis: "Mekke", konu: "Ashâb-ı Kehf, iki bahçe sahibi, Mûsâ-Hızır ve Zülkarneyn kıssaları.", fazilet: "Cuma günü okunmak sünnettir; iki cuma arasını nurlandırdığı rivayet edilir. Fitne günlerinde sığınak surelerdendir.", aciklama: "Dört büyük kıssa tek çatı altında: din baskısından kaçan Ashâb-ı Kehf'in yüzlerce yıllık uykusu, iki bahçeyi unutan zenginin helaki, Mûsâ'nın Hızır'la yolculuğunda 'bilmediğin şeyden sorulmaz' dersi ve iki dünyaya hükmeden Zülkarneyn'in adaleti. Her kıssa bir fitneye cevaptır: dine baskıya sabır, mala gönül bağlamama, bilmediğimize tevazu ve iktidara kibirlenmeme. Sure bunları, 'bunu kalbi yumuşasın diye anlattık' diye özetler.", nuzul: "Kehf suresi Mekke döneminde nazil olmuştur. Tefsirlerde, müşriklerin Yahudi bilginlerin telkiniyle Resûlullah’a Ashâb-ı Kehf, rûh ve Zülkarneyn hakkında soru sormaları ve cevabın bu surede gelmesi bağlamı aktarılır (Buhârî ve tefsirlerde ‘rûh’ sorusuyla ilgili bağlam ayrıca anılır). Rivayet ayrıntıları tartışmalı olabilir; kesin çekirdek, surenin imtihan/fetne karşısında sabır, tevazu ve doğru yönelişi dört kıssayla öğretmesidir. Cuma okunmasıyla ilgili fazilet rivayetleri için kaynaklar ayrıca değerlendirilir.", nuzul_en: "Surah al-Kahf was revealed in the Meccan period. Reports in tafsir literature connect it to questions posed to the Prophet about the People of the Cave, the spirit, and Dhul-Qarnayn. Details of the reports may be discussed, but the clear core is its teaching through four narratives: patience under trial, humility, and right orientation in times of fitnah. Reports about reciting it on Friday are transmitted in hadith literature and should be cited carefully.", nuzul_ar: "نزلت سورة الكهف في العهد المكي. وتذكر كتب التفسير أسئلة وُجهت للنبي عن أصحاب الكهف والروح وذي القرنين فجاء الجواب في السورة، مع اختلاف في بعض التفاصيل. والثابت تعليم السورة الصبر والتواضع وحسن التوجه عند الفتن من خلال أربع قصص. وتُروى أحاديث في فضل قراءتها يوم الجمعة.", nuzul_id: "Surah al-Kahf turun pada periode Mekah. Literatur tafsir mengaitkannya dengan pertanyaan kepada Nabi tentang Ashabul Kahfi, ruh, dan Dzulqarnain. Rincian riwayat dapat dibahas, tetapi inti yang jelas adalah pelajaran sabar dalam ujian, kerendahan hati, dan orientasi yang benar melalui empat kisah. Riwayat keutamaan membacanya pada hari Jumat ada dalam literatur hadis dan perlu dikutip hati-hati.", nuzul_ur: "سورۃ کہف مکی دور میں نازل ہوئی۔ تفسیری روایات اسے اصحاب کہف، روح اور ذوالقرنین کے بارے میں سوالات سے جوڑتی ہیں؛ تفصیلات میں اختلاف ہو سکتا ہے۔ واضح مرکز چار قصوں کے ذریعے فتنہ میں صبر، تواضع اور درست سمت کی تعلیم ہے۔ جمعہ کے دن تلاوت کی فضیلت کی روایات حدیثی ادب میں ہیں، انہیں احتیاط سے نقل کرنا چاہیے۔" },
  { n: 19, ad: "Meryem", inis: "Mekke", konu: "Kur'an'da adıyla anılan tek kadın: Meryem'in mucizesi, Zekeriya'nın duası.", fazilet: "Doğum ve aile kurma imtihanlarında okunması güzeldir; Allah'ın rahmetinin kadına özel tecellisini anlatan suredir.", aciklama: "İsmini, Kur'an'da adıyla andığı tek kadın olan Meryem'den alır. Zekeriya'nın yaşlılığına rağmen evlat duası, Meryem'in karnındaki İsa mucizesi, İbrahim'in putperest babasına yumuşak mücadelesi ve Mûsâ-İsmail-İdris kıssaları birbirine dokunur. Sure, 'Rahman evlat edindi' iddiasına cevap verir; Allah'a yalvaran her kalbin sesinin işitildiğini gösterir — yaşlı Zekeriya'nın duası kabul olunca işaret diliyle konuşmaya mecbur kalmıştır. Doğum, evlat ve aile imtihanlarında okunması güzeldir.", nuzul: "Meryem suresi Mekke döneminde nazil olmuştur. Sure; Zekeriya’nın duası, Meryem ve İsa’nın doğumu, İbrahim’in tevhid daveti gibi kıssalarla müşrik iddialarına ve ümmetin zorlandığı döneme imanî teselli sunar. Habeşistan hicreti bağlamında Müslümanların Hz. İsa ve Meryem hakkındaki inancını Kur’an diliyle açıklaması tefsir ve siyer literatüründe anılır (ayrıntılar kaynaklara göre değişir). Sure, rahmet ve doğru itikadı merkeze alır.", nuzul_en: "Surah Maryam was revealed in the Meccan period. Through narratives of Zechariah, Mary, Jesus, and Abraham, it offers faith-based reassurance and clarifies core beliefs against false claims. In sirah and tafsir literature, its language is also connected to how Muslims explained beliefs about Jesus and Mary in the Abyssinian migration context; details vary by source. The surah centers mercy and sound creed.", nuzul_ar: "نزلت سورة مريم في العهد المكي. تعرض قصص زكريا ومريم وعيسى وإبراهيم فتثبت العقيدة وتواسي المؤمنين. وتذكر مصادر السيرة والتفسير صلة معانيها ببيان المسلمين لعقيدتهم في عيسى ومريم في سياق الهجرة إلى الحبشة مع اختلاف في التفاصيل. ومحور السورة الرحمة وصحة الاعتقاد.", nuzul_id: "Surah Maryam turun pada periode Mekah. Melalui kisah Zakaria, Maryam, Isa, dan Ibrahim, surah ini meneguhkan iman dan meluruskan keyakinan. Dalam literatur sirah dan tafsir, bahasanya juga dikaitkan dengan penjelasan Muslim tentang keyakinan kepada Isa dan Maryam dalam konteks hijrah Habasyah; rincian berbeda antar sumber. Pusatnya adalah rahmat dan akidah yang benar.", nuzul_ur: "سورۃ مریم مکی دور میں نازل ہوئی۔ زکریا، مریم، عیسیٰ اور ابراہیم کے واقعات کے ذریعے ایمان کی تقویت اور عقیدے کی وضاحت کرتی ہے۔ سیرت و تفسیر میں اس کے مضامین کو حبشہ کی ہجرت کے پس منظر میں حضرت عیسیٰ و مریم کے بارے میں مسلمانوں کے بیان سے بھی جوڑا جاتا ہے؛ تفصیلات مختلف ہو سکتی ہیں۔ محور رحمت اور درست عقیدہ ہے۔" },
  { n: 24, ad: "Nûr", inis: "Medine", konu: "Ahlakın güvence altına alındığı sure; kalbi Nur Ayeti'dir.", fazilet: "Nur Ayeti, imanın kalpteki ışığını en berrak anlatan ayettir; iftira ve dedikoduya karşı ahlak kalkanıdır.", aciklama: "Toplumsal ahlakın güvenceye alındığı sure: zina cezası, iftira hadisesi, evlere izinle girme, bakış haramı ve nikâh kuralları sıralanır. Kalbi ise 35. ayettir: 'Allah göklerin ve yerin nurudur' — imanın insan gönlündeki ışığı, misal-i nuriye ile anlatılır. Sure, dedikodu ve iftiranın toplumu nasıl çürüttüğünü de gösterir; 'duymadığınız şeyi neden yaydınız?' sorusu sosyal medya çağında bile tazedir.", nuzul: "Nûr suresi Medine döneminde nazil olmuştur. İffet, iftira, ev adabı, tesettür ve toplumsal ahlak hükümleri bu dönemin sosyal ihtiyaçlarıyla doğrudan ilişkilidir. 11-20. ayetler, Hz. Âişe’ye atılan iftira (ifk) hadisesi bağlamında ele alınır; bu olayın ayrıntıları siyer/hadis kaynaklarında geçer ve masumiyet beyanı Kur’an’da sabittir (24:11-20). Ayetler, dedikodu ve zannın toplumda açtığı yarayı da gösterir.", nuzul_en: "Surah an-Nur was revealed in the Madinan period. Its rulings on chastity, slander, home etiquette, modesty, and social ethics address Madinan community needs. Verses 11–20 are connected to the slander incident (al-ifk) involving Aisha; details appear in sirah/hadith sources, while the Qur’an affirms her innocence (24:11–20) and warns against spreading suspicion.", nuzul_ar: "نزلت سورة النور في المدينة. وتعالج أحكام العفة والقذف وآداب البيوت والحشمة والأخلاق الاجتماعية. وترتبط الآيات 11-20 بحادثة الإفك، وتعرض تفاصيلها مصادر السيرة والحديث، بينما يقرر القرآن براءة عائشة رضي الله عنها ويحذر من إشاعة الظن.", nuzul_id: "Surah an-Nur turun di periode Madinah. Hukumnya tentang kesucian, tuduhan zina, adab rumah, kesopanan, dan etika sosial menjawab kebutuhan masyarakat Madinah. Ayat 11–20 dikaitkan dengan peristiwa ifk terhadap Aisyah; rincian ada di sirah/hadis, sementara Al-Qur’an menegaskan kebersihannya (24:11–20) dan memperingatkan penyebaran prasangka.", nuzul_ur: "سورۃ نور مدنی دور میں نازل ہوئی۔ عفت، تہمت، گھریلو آداب، حیا اور سماجی اخلاق کے احکام مدنی معاشرے کی ضرورت سے جڑے ہیں۔ آیات 11–20 واقعۂ افک سے متعلق ہیں؛ تفصیلات سیرت/حدیث میں ہیں جبکہ قرآن عائشہ رضی اللہ عنہا کی براءت بیان کرتا ہے (24:11–20) اور گمان پھیلانے سے روکتا ہے۔" },
  { n: 36, ad: "Yâsîn", inis: "Mekke", konu: "Ölüm, diriliş ve vahyin haklığı; kalbe dokunan üslup.", fazilet: "Kalb-i Kur'an denir; hastaya ve vefat edenlere okunur. Zor günlerde kalbe dokunan surelerden biridir.", aciklama: "Kur'an'ın kalbi sayılan sure: üç peygamberin 'size gönderildik' sahnesi, halkın 'siz bizim gibisiniz' itirazı ve kalbi dönmüş adamın 'arkamdan kavmimi uyarın' deyişle şehadeti anlatılır. Ölüm anındaki 'keşke' hali, dirilişin topraktan biten çiçekle kanıtı ve gökteki tertipli düzen, hepsi akla-heyecana seslenir. Üslubu o kadar kalbe dokunur ki, 'Kur'an'ın kalbi' sıfatı bunu özetler.", nuzul: "Yâsîn suresi Mekke döneminde nazil olmuştur. Mekke müşriklerinin nübüvveti ve ahireti inkâr ettiği ortamda vahyin doğruluğunu, risaletin yükünü ve diriliş gerçeğini güçlü bir üslupla hatırlatır. Suredeki ‘belde halkı’ kıssası, tebliğe karşı tutumları sembolik/ibret amaçlı sunar; kıssanın tarihî kimliği hakkında tefsirlerde farklı görüşler bulunur, bu nedenle kesin bir yer/isim iddiasından kaçınmak uygundur.", nuzul_en: "Surah Ya-Sin was revealed in the Meccan period. In a context where Meccan opponents denied prophethood and resurrection, it powerfully affirms revelation, messengerhood, and the Hereafter. The parable of the town’s people is presented as a lesson; tafsir works differ on historical identification, so caution is appropriate about naming a specific place.", nuzul_ar: "نزلت سورة يس في العهد المكي. وفي سياق إنكار النبوة والبعث أكدت الوحي والرسالة والآخرة بأسلوب بليغ. وقصة أصحاب القرية تُعرض للعبرة، مع اختلاف المفسرين في تعيينها التاريخي، فالأولى عدم الجزم بمكان معين.", nuzul_id: "Surah Ya-Sin turun di periode Mekah. Dalam konteks penolakan kenabian dan kebangkitan, surah ini menegaskan wahyu, kerasulan, dan akhirat. Perumpamaan penduduk negeri disampaikan sebagai ibrah; tafsir berbeda dalam identifikasi historisnya, sehingga perlu hati-hati menetapkan tempat tertentu.", nuzul_ur: "سورۃ یٰسین مکی دور میں نازل ہوئی۔ نبوت اور آخرت کے انکار کے ماحول میں وحی، رسالت اور قیامت کی حقیقت کو مؤثر انداز میں بیان کرتی ہے۔ بستی والوں کا واقعہ عبرت کے طور پر ہے؛ تاریخی تعیین میں مفسرین کے اختلاف کے باعث مخصوص مقام پر جزم مناسب نہیں۔" },
  { n: 55, ad: "Rahmân", inis: "Medine", konu: "Allah'ın nimetleri ve cennet tabloları — 'hangi nimetleri yalanlarsınız' nakaratı.", fazilet: "Cennet nimetlerini en canlı anlatan suredir; nakaratıyla akılda en çok kalan surelerdendir.", aciklama: "Göklerin-yerin yaratılışından güneş-ayın hesapla akmasına, iki doğunun (şark-garb) dönmesine kadar Allah'ın kusursuz düzeni sayılır; sonra cennet tabloları açılır: iki bahçe, iki pınar, her meyveden çift çift. 31 kez tekrarlanan 'fa-bi-eyyi âlâi rabbikümâ tükezzibân' (hangi nimetlerinizi yalanlarsınız?) nakaratı, insanı ve cini hesaba çeker. Kıyamet ve cehennem sahnesi anlatıldıktan sonra cennetle bitmesi, umudu güçlendirir.", nuzul: "Rahmân suresi iniş yeri bakımından Mekke ve Medine rivayetleri bulunan surelerdendir; tefsirlerde her iki görüş aktarılır. İçeriği, Allah’ın yaratma ve nimet verme rubûbiyetini hem insan hem cin muhataplarına hatırlatır. ‘Hangi Rabbinizin nimetlerini yalanlıyorsunuz?’ nakaratı, nüzul bağlamını belirli bir olaya sıkıştırmadan nimete şükür ve sorumluluk bilinci kurar.", nuzul_en: "Surah ar-Rahman is discussed with both Meccan and Medinan reports regarding place of revelation. Its content addresses both humans and jinn, recalling Allah’s lordship in creation and blessings. The refrain about denying the Lord’s favors establishes gratitude and responsibility without tying the surah to one narrow incident.", nuzul_ar: "تُذكر في مكان نزول الرحمن أقوال مكية ومدنية. ويخاطب السورة الإنس والجن مذكّرة بربوبية الله ونِعمه. وتقرر الآية المكررة معنى الشكر والمسؤولية دون حصر السورة في حادثة واحدة.", nuzul_id: "Tempat turunnya Surah ar-Rahman dibahas dengan riwayat Mekah dan Madinah. Isinya menegur manusia dan jin, mengingatkan ketuhanan Allah dalam ciptaan dan nikmat. Pengulangan ayat tentang nikmat Tuhan membangun syukur dan tanggung jawab tanpa mengikat surah pada satu peristiwa sempit.", nuzul_ur: "سورۃ الرحمن کے مقام نزول میں مکی اور مدنی روایات ملتی ہیں۔ یہ انسان و جن کو مخاطب کر کے ربوبیت اور نعمتوں کی یاد دہانی کرتی ہے۔ بار بار آنے والی آیت شکر اور ذمہ داری کا احساس پیدا کرتی ہے، کسی ایک واقعے تک محدود کیے بغیر۔" },
  { n: 56, ad: "Vâkıa", inis: "Mekke", konu: "Kıyamet sahnesi; üç grup insan (takva, aşire-i yemin, aşire-i şimâl).", fazilet: "Fakirlikten korunmak için akşam okunması rivayet edilmiştir; rızık endişesiyle okunması güzel bir sünnettir.", aciklama: "Kıyamet inkâr edilemez ve insanlar üç gruba ayrılır: öncüler (sâbikûn), sağ el sahipleri ve sol el sahipleri; her grubun hâli tafsilatıyla resmedilir. Cennetin huzuru, 'boş ve bâtıl söz duymazsınız' cümlesiyle taçlanır. Rızık ayetleri meşhurdur: 'O, sizin için yerde ve gökte rızık yarattı' — Allah rızık sahibidir; insan çalışır ama vereni Odur.", nuzul: "Vâkıa suresi Mekke döneminde nazil olmuştur. Kıyametin kopuşu, insanların gruplara ayrılması ve ahiret sonuçları, Mekke’de ahireti inkâr eden muhataplara güçlü tasvirlerle sunulur. Sure; ödül, ceza, yeniden diriliş ve rızık gibi meseleleri tevhid-akide ekseninde işler. Rızık/fakirlik konusunda aktarılan fazilet rivayetleri için isnad ve ifade ihtiyatla ele alınmalıdır; asıl odak suredeki ahiret bilincidir.", nuzul_en: "Surah al-Waqi‘ah was revealed in the Meccan period. It addresses audiences who denied the Hereafter by vividly portraying the coming event, the grouping of people, and final outcomes. It treats resurrection, recompense, and provision within creed. Reports about reciting it for worldly provision should be handled cautiously; the surah’s primary focus is accountability in the Hereafter.", nuzul_ar: "نزلت سورة الواقعة في العهد المكي. تخاطب منكري الآخرة بتصوير قيام الساعة وأصناف الناس والجزاء. وتعالج البعث والمصير والرزق في إطار العقيدة. وينبغي التثبت في الروايات المتعلقة بقراءتها لأجل الرزق، فمحورها الأساسي الاستعداد للآخرة.", nuzul_id: "Surah al-Waqi‘ah turun di periode Mekah. Ia berbicara kepada penolak akhirat dengan gambaran peristiwa kiamat, pengelompokan manusia, dan akibat akhir. Kebangkitan, balasan, dan rezeki dibahas dalam kerangka akidah. Riwayat tentang membacanya untuk rezeki perlu kehati-hatian; fokus utamanya adalah kesadaran akhirat.", nuzul_ur: "سورۃ واقعہ مکی دور میں نازل ہوئی۔ آخرت کے منکرین کے سامنے قیامت، لوگوں کی تقسیم اور انجام کو واضح انداز میں پیش کرتی ہے۔ بعث، جزا اور رزق کو عقیدے کے محور پر بیان کرتی ہے۔ رزق کے لیے تلاوت کی روایات میں تحقیق ضروری ہے؛ بنیادی مرکز آخرت کی تیاری ہے۔" },
  { n: 67, ad: "Mülk", inis: "Mekke", konu: "Allah'ın mülkü, yaratılış hikmeti ve kâfirlerin akibeti.", fazilet: "Uyuduktan önce okunması sünnettir; kabir azabından koruma rivayet edilir.", aciklama: "Allah'ın mülkü ve ölümün imtihan olarak yaratılması beyan edilir: 'Ölümü yaratan, hanginizin daha güzel amel işlediğini denemek içindir.' Göğün yedi kat olarak tertiplendiği, 'gökyüzünde düzen bozukluğu gördün mü?' sorusuyla akla sunulur. Kabir sahnesinde mümine 'bugün ne okuyordun?' diye sorulur; sure adını bu sahneden alır.", nuzul: "Mülk (Tebâreke) suresi Mekke döneminde nazil olmuştur. Allah’ın mülk sahibi oluşu, göklerin düzeni, ölüm-hayat imtihanı ve inkâr edenlerin sorumluluğu Mekke tebliğinin ana konularıyla uyumludur. Surenin korunma faziletiyle ilgili hadis rivayetleri vardır; bu rivayetler hadis kaynaklarında değerlendirilir (ör. Tirmizî’de geçen rivayetler çeşitli sened değerlendirmelerine tabidir), bu yüzden ifade temkinli tutulmalıdır.", nuzul_en: "Surah al-Mulk (Tabarak) was revealed in the Meccan period. Its themes—Allah’s sovereignty, the ordered heavens, life and death as a test, and human accountability—fit the core of Meccan proclamation. Hadith reports mention virtues related to protection; these reports are evaluated in hadith scholarship with varying grading, so statements should remain cautious.", nuzul_ar: "نزلت سورة الملك في العهد المكي. ومحاورها—ملك الله ونظام السماوات وابتلاء الحياة والموت والمسؤولية—تنسجم مع الدعوة المكية. وترد أحاديث في فضلها، وهي خاضعة للنظر في علوم الحديث، فينبغي التعبير بتحفظ.", nuzul_id: "Surah al-Mulk (Tabarak) turun di periode Mekah. Temanya—kedaulatan Allah, keteraturan langit, ujian hidup-mati, dan pertanggungjawaban—selaras dengan dakwah Mekah. Ada riwayat hadis tentang keutamaannya; riwayat ini dinilai dalam ilmu hadis, sehingga penyampaian perlu berhati-hati.", nuzul_ur: "سورۃ ملک (تبارک) مکی دور میں نازل ہوئی۔ اللہ کی بادشاہت، آسمانی نظم، زندگی و موت کی آزمائش اور جوابدہی مکی دعوت کے اہم مضامین ہیں۔ فضیلت کی احادیث ملتی ہیں جن کی تحقیق علومِ حدیث میں ہوتی ہے، اس لیے بیان میں احتیاط مناسب ہے۔" },
  { n: 78, ad: "Nebe", inis: "Mekke", konu: "'Yüce haber ne'dir?' — kıyametin en net beyanı.", fazilet: "Namazlarda en çok duyulan surelerdendir; kıyamet akidesini en temiz kuran sureler arasındadır.", aciklama: "Sure, 'Birbirlerine yüce haberden mi soruyorlar?' sorusuyla açılır: yüce haber, kıyamet gerçeğidir. Dünyanın döşek yapıldığı, dağların yürütüldüğü, cehennemin ve cennetin gerçek hâli anlatılır. 'İşte o gün fâsıl gündür' — hesabın kaçınılmazlığını en net kuran akaid dersidir; 30. cüz'ün (Jüz'ü Amme) ilk suresidir.", nuzul: "Nebe suresi Mekke döneminde nazil olmuştur. Mekkelilerin ‘büyük haber’ olarak kıyamet ve diriliş hakkında soru sormaları/şüphe taşımaları bağlamında, sure kıyametin gerçekliğini, ölümden sonra dirilişi ve hesap gününü açık deliller ve tabiat sahneleriyle kurar. Juz Amma’nın güçlü giriş surelerinden biri olarak Mekke tebliğinde ahiret inancını yerleştirmeyi hedefler.", nuzul_en: "Surah an-Naba was revealed in the Meccan period. Responding to doubt and questioning about the ‘great news’ of resurrection and judgment, it establishes the reality of the Hereafter with clear signs and scenes from creation. As an early powerful surah of Juz Amma, it supports the Meccan call to belief in accountability.", nuzul_ar: "نزلت سورة النبأ في العهد المكي. وتجيب عن تساؤل المشركين وشكهم في النبأ العظيم، فتقرر حقيقة البعث والحساب بأدلة ومشاهد من الخلق. وهي من سور جزء عم المؤثرة في تثبيت الإيمان بالآخرة.", nuzul_id: "Surah an-Naba turun di periode Mekah. Menjawab keraguan tentang ‘berita besar’ kebangkitan dan penghakiman, surah ini menegaskan akhirat dengan tanda-tanda dan gambaran ciptaan. Sebagai surah awal Juz Amma, ia memperkuat dakwah Mekah tentang pertanggungjawaban.", nuzul_ur: "سورۃ النبأ مکی دور میں نازل ہوئی۔ ‘نبأ عظیم’ یعنی قیامت و بعث کے بارے میں سوال و شک کے ماحول میں یہ سورت واضح دلائل اور کائناتی نشانیوں سے آخرت کی حقیقت قائم کرتی ہے۔ جز عم کی مؤثر ابتدائی سورتوں میں سے ہے۔" },
  { n: 93, ad: "Duhâ", inis: "Mekke", konu: "'Rabbin seni terk etmedi, darılmadı' — kırgın kalbe ilaç.", fazilet: "Yetim ve kimsesizle ilgilenenlerin okuması tavsiye edilir; 'seni terk etmedi' müjdesi kırgın kalbe ilaçtır.", aciklama: "Kuşluk vakti inen, Peygamber'e (s.a.v.) en samimi hitaplardan biridir: 'Rabbin seni terk etmedi ve darılmadı.' Yetimliği anılıp yetim hakkı, isteyeni azarlamama ve nimeti duyurma öğütlenir. 'Rabbin seni razı edecek' müjdesiyle biter; kırgın, yalnız ve yorgun kalbe en çok dokunan surelerdendir.", nuzul: "Duhâ suresi Mekke döneminde nazil olmuştur. Rivayetlerde vahyin bir süre gelmemesi üzerine müşriklerin Hz. Peygamber’e üzücü sözler söylediği ve surenin teselli olarak indiği aktarılır; rivayetlerin bazı ayrıntıları farklılık gösterebilir. Kesin mesaj, Allah’ın Resulünü terk etmediği, yetimlik/nimet hatırlatması ve yetime/yoksula iyi davranma çağrısıdır (93:3-11).", nuzul_en: "Surah ad-Duha was revealed in the Meccan period. Reports mention a pause in revelation after which opponents spoke hurtfully to the Prophet, and the surah came as consolation; details vary in reports. Its clear message is that Allah did not forsake His Messenger, along with reminders of care and commands to treat the orphan and needy kindly (93:3–11).", nuzul_ar: "نزلت سورة الضحى في العهد المكي. وتذكر روايات فترة انقطاع الوحي وما تبعها من أذى قول، فنزلت السورة مواساة؛ وتختلف بعض تفاصيل الروايات. ورسالتها الثابتة أن الله لم يترك رسوله، مع التذكير بالنعم والوصية باليتيم والسائل.", nuzul_id: "Surah ad-Duha turun di periode Mekah. Riwayat menyebut jeda wahyu dan ucapan menyakitkan dari penentang, lalu surah ini turun sebagai penghiburan; rincian riwayat dapat berbeda. Pesan jelasnya: Allah tidak meninggalkan Rasul-Nya, disertai pengingat nikmat dan perintah berbuat baik kepada yatim serta peminta-minta (93:3–11).", nuzul_ur: "سورۃ الضحیٰ مکی دور میں نازل ہوئی۔ روایات میں وحی کے توقف اور مخالفوں کی دل آزار باتوں کا ذکر ہے اور یہ سورت تسلی کے طور پر نازل ہوئی؛ تفصیلات مختلف ہو سکتی ہیں۔ واضح پیام یہ ہے کہ اللہ نے اپنے رسول کو نہیں چھوڑا، نیز نعمتوں کی یاد دہانی اور یتیم و سائل سے حسنِ سلوک کی ہدایت ہے (93:3–11)۔" },
  { n: 94, ad: "İnşirâh", inis: "Mekke", konu: "'Güçlükle beraber kolaylık' — yorguna çift müjde.", fazilet: "'Zorluk kolaylığa zincirlidir' müjdesi sınav, borç ve yorgunluk anında okunur; 6. ayet en çok paylaşılan ayetlerdendir.", aciklama: "'Kalbini genişletmedik mi?' sorularıyla açılır ve 'şüphesiz güçle beraber kolaylıktır' müjdesi iki kez tekrarlanır — bir zorluk, iki kolaylıkla çözülür. 'İşin bitince yorul, Rabbine yönel' ayeti çalışma ahlakının özüdür: didin, ama yönünü Rabbine koru. Zorluk dönemlerinde en çok okunan surelerdendir.", nuzul: "İnşirâh (Şerh) suresi Mekke döneminde nazil olmuştur ve genellikle Duhâ ile aynı teselli bağlamında okunur. Sure, sıkıntıyla beraber kolaylığın bulunduğunu bildirir ve Resûlullah’a manevi yükün hafifletildiğini hatırlatır. Mekke baskısı altında sabır, görev bilinci ve ibadetle yöneliş mesajı verir.", nuzul_en: "Surah ash-Sharh (al-Inshirah) was revealed in the Meccan period and is often read in continuity with ad-Duha as consolation. It declares ease with hardship and reminds the Prophet of relief granted to him. In the pressure of Mecca, it calls to patience, purpose, and turning to worship.", nuzul_ar: "نزلت سورة الشرح في العهد المكي، وغالبا ما تُقرأ مع الضحى في سياق المواساة. تقرر أن مع العسر يسرا وتذكر بتيسير الحمل عن النبي. وفي ضغط مكة تدعو إلى الصبر والقيام بالرسالة والإقبال على العبادة.", nuzul_id: "Surah asy-Syarh (al-Insyirah) turun di periode Mekah dan sering dibaca berkaitan dengan ad-Duha sebagai penghiburan. Ia menyatakan kemudahan bersama kesulitan dan mengingatkan keringanan beban Nabi. Di tengah tekanan Mekah, ia menyeru sabar, keteguhan tugas, dan kembali beribadah.", nuzul_ur: "سورۃ الانشراح مکی دور میں نازل ہوئی اور اکثر ضحیٰ کے ساتھ تسلی کے سیاق میں پڑھی جاتی ہے۔ یہ تنگی کے ساتھ آسانی کا اعلان کرتی ہے اور رسول پر بوجھ کی تخفیف کی یاد دلاتی ہے۔ مکی دباؤ میں صبر، ذمہ داری اور عبادت کی طرف رجوع کی دعوت دیتی ہے۔" },
  { n: 97, ad: "Kadr", inis: "Mekke", konu: "Kadir Gecesi: bin aydan hayırlı gece.", fazilet: "Kadir Gecesi'nde en çok okunan suredir; son on gecede ihya önerilir, geceyi bulanın affedileceği rivayet edilir.", aciklama: "Kur'an'ın indirildiği gecenin değeri anlatılır: 'Bin aydan hayırlıdır' — seksen üç yıllık ibadetten bile üstün bir gece. Melekler ve Ruh (Cebrail) o gece yer yüzüne iner; gece boyunca selâmettir, fecre kadar sürer. Ramazan'ın son on gecesinde aranan bu gece, ibadet ömrünü bin ayın üzerine çıkarır.", nuzul: "Kadir suresi Mekke döneminde nazil olmuştur. Kur’an’ın indirilmeye başlandığı Kadir gecesinin değerini bildirir; bu gece hicrî Ramazan’ın son on gününde aranır ve tek bir gecenin bin aydan hayırlı olduğu vurgulanır (97:1-5). Kadir gecesinin hangi gece olduğuna dair rivayetler farklıdır; ibadet ve tefekkür yönü kesindir.", nuzul_en: "Surah al-Qadr was revealed in the Meccan period. It announces the greatness of the Night of Decree, when the Qur’an began to be revealed; it is sought in the last ten nights of Ramadan and described as better than a thousand months (97:1–5). Reports differ about the exact night; devotion and reflection are the clear focus.", nuzul_ar: "نزلت سورة القدر في العهد المكي. تبين فضل ليلة القدر التي بدأ فيها نزول القرآن، وتُلتمس في العشر الأواخر من رمضان، وهي خير من ألف شهر (97:1-5). وتختلف الروايات في تعيينها، والثابت فضل العبادة والتدبر.", nuzul_id: "Surah al-Qadr turun di periode Mekah. Ia menyatakan kemuliaan Lailatul Qadar saat Al-Qur’an mulai diturunkan; malam itu dicari pada sepuluh malam terakhir Ramadhan dan lebih baik dari seribu bulan (97:1–5). Riwayat berbeda tentang malam pastinya; fokusnya ibadah dan perenungan.", nuzul_ur: "سورۃ القدر مکی دور میں نازل ہوئی۔ اس میں شبِ قدر کی فضیلت بیان ہے جس میں قرآن کا نزول شروع ہوا؛ اسے رمضان کے آخری عشرے میں تلاش کیا جاتا ہے اور یہ ہزار مہینوں سے بہتر ہے (97:1–5)۔ عین رات کے تعین میں روایات مختلف ہیں؛ عبادت و تدبر واضح ہے۔" },
  { n: 99, ad: "Zilzâl", inis: "Medine", konu: "Yerin son sarsıntısı ve zerre ağırlığınca hesap.", fazilet: "Namazlarda sık okunur; hesap bilinci için okunması tavsiye edilir.", aciklama: "Yerin son sarsıntısı ve 'yer, haberlerini dışarı çıkarır' sahnesi anlatılır; insanlar tek tek amel defterlerini görür: 'Zerre ağırlınca hayır da, şer de görürsünüz.' Kısa ama akideyi temel atmaya yetecek kadar derindir — hesap bilinci, günlük ahlakın faturasıdır.", nuzul: "Zilzâl suresi iniş yeri hakkında Mekke ve Medine rivayetleri bulunan surelerdendir. Kıyamet günü yerin sarsılması ve yaptıkların ortaya konmasıyla, en küçük hayır ve şerrin dahi karşılığının görüleceğini bildirir (99:1-8). Bu güçlü ahiret sahnesi, amelde sorumluluk bilincini canlı tutmayı amaçlar.", nuzul_en: "Surah az-Zalzalah is reported with both Meccan and Medinan attributions. It depicts the earth’s convulsion on the Last Day and states that even the smallest good or evil will be seen (99:1–8). The scene aims to keep moral accountability alive.", nuzul_ar: "تُذكر سورة الزلزلة بأقوال مكية ومدنية. تصور زلزال الأرض يوم القيامة وإظهار الأعمال، وأن مثقال ذرة من خير أو شر يُرى (99:1-8). والمشهد يرسخ مسؤولية العمل.", nuzul_id: "Surah az-Zalzalah diriwayatkan dengan pendapat Mekah dan Madinah. Ia menggambarkan guncangan bumi di Hari Akhir dan menyatakan bahwa sekecil apa pun kebaikan atau keburukan akan terlihat (99:1–8). Tujuannya menjaga kesadaran pertanggungjawaban.", nuzul_ur: "سورۃ الزلزال کے نزول میں مکی اور مدنی دونوں اقوال ملتے ہیں۔ قیامت کے دن زمین کے زلزلے اور اعمال کے ظاہر ہونے، نیز ذرے برابر نیکی و بدی کے سامنے آنے کو بیان کرتی ہے (99:1–8)۔ مقصد عمل کی جوابدہی کو زندہ رکھنا ہے۔" },
  { n: 103, ad: "Asr", inis: "Mekke", konu: "İki ayette İslam'ın özeti: iman, salih amel, hak ve sabra tavsiye.", fazilet: "Şâfiî: 'İnsanlar Asr sûresini tefekkür etselerdi, başka öğreticiye ihtiyaç duymazlardı.' Namazlarda en sık okunan surelerdendir.", aciklama: "İki ayetlik ama 'Kur'an'ın dörtte birini özetleyen' sure sayılır (İmam Şâfiî). Zamana yemin edilir: insan hüsrandadır — kural değil istisna. Kurtuluş dört şarttır: iman, salih amel, hakka tavsiye ve sabra tavsiye. İman tek başına yetmez; amel ister, dayanışma ister, sabır ister — İslam'ın en yoğun özeti buradadır.", nuzul: "Asr suresi Mekke döneminde nazil olmuştur. Kısa ama kapsamlı bir ölçüt koyar: insanın hüsranda olduğu uyarısı, iman edenler, salih amel işleyenler, birbirine hakkı ve sabrı tavsiye edenler için istisna ile dengelenir (103:1-3). Nüzul bağlamı belirli bir olaya indirgenmez; zamanın kıymeti ve sorumluluk bilinci ana mesajdır.", nuzul_en: "Surah al-Asr was revealed in the Meccan period. Brief yet comprehensive, it warns that humankind is in loss, except those who believe, do righteous deeds, and counsel one another to truth and patience (103:1–3). It is not tied to a single incident; its core is the value of time and moral responsibility.", nuzul_ar: "نزلت سورة العصر في العهد المكي. وتضع معيارا جامعا: خسران الإنسان إلا من آمن وعمل صالحا وتواصى بالحق والصبر (103:1-3). ولا تُربط بحادثة واحدة، ومحورها قيمة الوقت والمسؤولية.", nuzul_id: "Surah al-Asr turun di periode Mekah. Singkat namun mencakup: manusia dalam kerugian kecuali beriman, beramal saleh, serta saling menasihati dalam kebenaran dan kesabaran (103:1–3). Tidak terikat satu peristiwa; intinya nilai waktu dan tanggung jawab.", nuzul_ur: "سورۃ العصر مکی دور میں نازل ہوئی۔ مختصر مگر جامع معیار دیتی ہے: انسان خسارے میں ہے سوائے ایمان، نیک عمل، حق کی وصیت اور صبر کی تلقین والوں کے (103:1–3)۔ کسی ایک واقعے سے خاص نہیں؛ وقت کی قدر اور ذمہ داری اس کا مرکز ہے۔" },
  { n: 105, ad: "Fîl", inis: "Mekke", konu: "Fillerle gelen ordu ve kuşların taşları — Kâbe'nin savunması.", fazilet: "Çocukların ilk ezberlediği surelerdendir; Allah'ın koruyan gücünü en somut anlatan kıssadır.", aciklama: "Yemen valisi Ebrehe'nin fil ordusuyla Kâbe'yi yıkmaya geldiği ve kuşların gönderdiği taşlarla helak olduğu olay anlatılır. Allah'ın evini kendisi korur: insan gücü ne kadar büyük olursa olsun, Allah'ın koruduğunu kimse yıkamaz. Peygamber'in (s.a.v.) doğduğu yıla 'Fil Yılı' denir; sure, bu olayla İslam tarihine açılan kapıdır.", nuzul: "Fil suresi Mekke döneminde nazil olmuştur. Habeş/Ebrehe ordusunun filleriyle Kâbe’ye yöneldiği ve ordunun helak olduğu olay (Âmü’l-Fil) Kur’an’da ibret sahnesi olarak hatırlatılır (105:1-5). Tarihî ayrıntılar siyer ve tarih kaynaklarında aktarılır; rivayetlerde farklı betimlemeler bulunabilir. Sure, Kâbe’nin Allah’ın koruması altında olduğunu ve zulmün sonunu gösterir.", nuzul_en: "Surah al-Fil was revealed in the Meccan period. It recalls the Year of the Elephant, when Abraha’s army advanced toward the Kaaba and was destroyed (105:1–5). Historical details appear in sirah and history sources with varying descriptions. The surah highlights divine protection of the Kaaba and the end of oppressive aggression.", nuzul_ar: "نزلت سورة الفيل في العهد المكي. تذكر عام الفيل حين توجه جيش أبرهة إلى الكعبة فأُهلك (105:1-5). وترد التفاصيل في السيرة والتاريخ مع اختلاف في بعض الأوصاف. وتبرز السورة حماية الله للكعبة وعاقبة البغي.", nuzul_id: "Surah al-Fil turun di periode Mekah. Ia mengingatkan Tahun Gajah, ketika pasukan Abrahah menuju Ka‘bah lalu binasa (105:1–5). Rincian sejarah ada di sirah dan sejarah dengan variasi gambaran. Surah ini menonjolkan perlindungan Allah atas Ka‘bah dan akibat kezaliman.", nuzul_ur: "سورۃ الفیل مکی دور میں نازل ہوئی۔ عام الفیل کا واقعہ یاد دلاتی ہے جب ابرہہ کا لشکر کعبہ کی طرف بڑھا اور ہلاک ہوا (105:1–5)۔ تاریخی تفصیلات سیرت و تاریخ میں ملتی ہیں، بیان مختلف ہو سکتے ہیں۔ سورت کعبہ کی حفاظت اور ظلم کے انجام کو نمایاں کرتی ہے۔" },
  { n: 106, ad: "Kureyş", inis: "Mekke", konu: "Kâbe'nin sahiplerine rızık ve güven lütfu.", fazilet: "Fîl ile aynı vahiy grubundandır, birlikte okunması yaygındır; rızık ve yol güvenliği duası olarak okunur.", aciklama: "Kureyş'in kış-yaz seferleri, açlıktan güvene çıkarılması ve Kâbe'ye hizmetinden gelen itibar anlatılır. 'Bu Beyt'in Rabbine kulluk etsinler' çağrısı, nimetin sahibine şükretmeye davettir. Ticaret güvenliği ve rızık bolluğu Allah'ın lütfudur; sure bu lütufa şükranı hatırlatır.", nuzul: "Kureyş suresi Mekke döneminde nazil olmuştur ve çoğu tefsirde Fil suresiyle anlam bağı içinde okunur. Kureyş’in güvenli ticaret yolculukları ve Kâbe’nin sağladığı emniyet nimetine dikkat çekilerek, bu nimetin sahibine kulluk çağrısı yapılır (106:1-4). Nüzul, şükür ve tevhid sorumluluğunu vurgular.", nuzul_en: "Surah Quraysh was revealed in the Meccan period and is often read in connection with al-Fil. It recalls the security and trade journeys of Quraysh and calls them to worship the Lord of the Kaaba who provided safety and provision (106:1–4). Its context emphasizes gratitude and tawhid.", nuzul_ar: "نزلت سورة قريش في العهد المكي، وكثيرا ما تُقرأ مع الفيل. تذكر أمن قريش ورحلاتهم التجارية وتدعوهم إلى عبادة رب البيت الذي أطعمهم وآمنهم (106:1-4). ومحورها الشكر والتوحيد.", nuzul_id: "Surah Quraisy turun di periode Mekah dan sering dibaca terkait al-Fil. Ia mengingatkan keamanan dan perjalanan dagang Quraisy serta menyeru mereka menyembah Tuhan Ka‘bah yang memberi makan dan rasa aman (106:1–4). Konteksnya menekankan syukur dan tauhid.", nuzul_ur: "سورۃ قریش مکی دور میں نازل ہوئی اور اکثر الفیل کے ساتھ معنوی ربط میں پڑھی جاتی ہے۔ قریش کی امن اور تجارتی سفر کی نعمت یاد دلا کر کعبہ کے رب کی عبادت کی دعوت دیتی ہے (106:1–4)۔ محور شکر اور توحید ہے۔" },
  { n: 107, ad: "Mâûn", inis: "Mekke", konu: "Din'in özü: yetime, fakire, gafletsiz namaza.", fazilet: "Hayır işlerinin dinî değerini hatırlatan sure; riya ve gafletle namaz kılanı uyarır.", aciklama: "'Dini yalanlayan kimse' tanımı şaşırtıcı biçimde ahlakla başlar: yetimi itelemek, fakiri doyurmaya yanaşmamak. Sonra ibadete döner: namazda gaflet, riya ve yardımı ketum tutmak. İbadetle ahlakı birleştiren en sert eleştirilerden biridir — namaz kıldığı hâlde yetim hakkı gözetmeyen kişi, dini yalanlıyordur.", nuzul: "Mâûn suresi iniş yeri hakkında Mekke ve Medine görüşleri bulunur. Namazda gösteriş yapan, yetimi iten ve küçük yardımları bile esirgeyen tutumları eleştirerek ibadet ile sosyal sorumluluk arasındaki bağı kurar (107:1-7). ‘Mâûn’ ifadesinin kapsamı tefsirde farklı açıklanmıştır; ortak ders, dindarlığın merhamet ve yardımla doğrulanmasıdır.", nuzul_en: "Surah al-Ma‘un has both Meccan and Medinan attributions. It criticizes ostentation in prayer, neglect of the orphan, and refusal of small kindnesses, linking worship to social responsibility (107:1–7). The scope of ‘ma‘un’ is discussed in tafsir; the shared lesson is that piety is verified by compassion and help.", nuzul_ar: "تُذكر سورة الماعون بأقوال مكية ومدنية. تنتقد الرياء في الصلاة ودفع اليتيم ومنع المعروف، فتربط العبادة بالمسؤولية الاجتماعية (107:1-7). ويُفسر الماعون بتفسيرات، والعبرة أن الإيمان يظهر بالرحمة.", nuzul_id: "Surah al-Ma‘un memiliki pendapat Mekah dan Madinah. Ia mengkritik riya dalam salat, menghardik anak yatim, dan menolak bantuan kecil, mengaitkan ibadah dengan tanggung jawab sosial (107:1–7). Cakupan ‘ma‘un’ dibahas tafsir; pelajarannya, kesalehan dibuktikan dengan kasih sayang dan bantuan.", nuzul_ur: "سورۃ الماعون کے نزول میں مکی اور مدنی اقوال ہیں۔ نماز میں ریا، یتیم کو دھتکارنے اور معمولی بھلائی روکنے پر تنقید کر کے عبادت کو سماجی ذمہ داری سے جوڑتی ہے (107:1–7)۔ ‘ماعون’ کی وسعت میں تفسیری اختلاف ہے؛ مشترکہ سبق رحمدلی اور مدد سے دین کی تصدیق ہے۔" },
  { n: 108, ad: "Kevser", inis: "Mekke", konu: "En kısa sure: bol nimet, kurban ve namaz.", fazilet: "En kısa sure olması nedeniyle namazlarda sık okunur; kurban keserken hatırlanır.", aciklama: "Kur'an'ın en kısa suresi — üç ayet. 'Kevser' cennet nehri ya da bolluk olarak tefsir edilir; Peygamber'e (s.a.v.) 'Rabbin için namaz kıl ve kurban kes' emri verilir. 'Sana nefret eden, zaten soyu kesiktir' — düşmanların sözlü saldırısına en sert cevap. Hz. Hasan'ın doğumuyla ilgili inmesi rivayet edilir; bolluk ve şükranın özüdür.", nuzul: "Kevser suresi Mekke döneminde nazil olmuştur. Rivayetlerde Hz. Peygamber’e evladı nedeniyle yöneltilen incitici sözler veya ‘kesik/soyu kesilmiş’ yakıştırmaları bağlamı aktarılır; ayrıntılar rivayetlere göre değişebilir. Sure, Peygamber’e bol hayır (kevser) verildiğini müjdeler ve onu namaz ile kurban/ibadete yönlendirir (108:1-3).", nuzul_en: "Surah al-Kawthar was revealed in the Meccan period. Reports connect it to hurtful taunts directed at the Prophet; details vary. The surah announces abundant good granted to him and directs him to prayer and devotion (108:1–3).", nuzul_ar: "نزلت سورة الكوثر في العهد المكي. وتذكر روايات سياق إيذاء بالقول للنبي مع اختلاف في التفاصيل. تبشر السورة بالعطاء الكثير وتأمره بالصلاة والنحر/العبادة (108:1-3).", nuzul_id: "Surah al-Kautsar turun di periode Mekah. Riwayat mengaitkannya dengan ejekan yang menyakitkan kepada Nabi; rinciannya berbeda. Surah ini mengabarkan kebaikan yang melimpah dan mengarahkan beliau kepada salat dan pengabdian (108:1–3).", nuzul_ur: "سورۃ کوثر مکی دور میں نازل ہوئی۔ روایات میں نبی کو پہنچائی گئی تکلیف دہ باتوں کا پس منظر آتا ہے؛ تفصیلات مختلف ہو سکتی ہیں۔ سورت فراوان خیر کی بشارت اور نماز و بندگی کی ہدایت دیتی ہے (108:1–3)۔" },
  { n: 109, ad: "Kâfirûn", inis: "Mekke", konu: "Tevhidin sınırı: 'Sizin dininiz size, benim dinim bana.'", fazilet: "Sabah-akşam okunması önerilir; şirk fitnesinden koruduğu rivayet edilir — tevhidin ilke beyanıdır.", aciklama: "Kureyş'in 'bir yıl senin dinine, bir yıl bizim dinimize tapalım' teklifine net cevaptır: 'Siz neye kulluk ederseniz edin, ben kulluk etmem; ben neye kulluk ediyorsam, siz etmezsiniz.' Sure küfürden değil, küfürle birleşmekten sakındırır; tevhidin sınırını çizer ve itidali korur. 'Sizin dininiz size, benim dinim bana' — dünya ilişkisi ayrı, ibadet ayrıdır.", nuzul: "Kâfirûn suresi Mekke döneminde nazil olmuştur. Rivayetlerde müşriklerin ortak ibadet/uzlaşma tekliflerine karşı tevhidi netleştiren bir beyan olarak indiği aktarılır; tekliflerin şekli hakkında rivayet farklılıkları vardır. Sure, inançta taviz vermeden karşılıklı sınırı açıkça koyar: ‘Sizin dininiz size, benim dinim bana’ (109:1-6). Bu ifade, inanç özgürlüğü ve tevhid kararlılığını birlikte yansıtır.", nuzul_en: "Surah al-Kafirun was revealed in the Meccan period. Reports connect it to proposals of religious compromise from Meccan opponents; details of the proposals vary. The surah clearly affirms monotheistic commitment without compromise: ‘To you your religion, and to me my religion’ (109:1–6), expressing firm faith and clear boundaries.", nuzul_ar: "نزلت سورة الكافرون في العهد المكي. وتذكر روايات عروضًا للمساومة الدينية مع اختلاف في صيغتها. تقرر السورة التوحيد دون مساومة: لكم دينكم ولي دين (109:1-6).", nuzul_id: "Surah al-Kafirun turun di periode Mekah. Riwayat mengaitkannya dengan tawaran kompromi agama; bentuk tawaran berbeda-beda. Surah ini menegaskan tauhid tanpa kompromi: ‘Bagimu agamamu, dan bagiku agamaku’ (109:1–6).", nuzul_ur: "سورۃ الکافرون مکی دور میں نازل ہوئی۔ روایات میں مذہبی مصالحت کی پیشکشوں کا ذکر ہے؛ تفصیلات مختلف ہو سکتی ہیں۔ سورت توحید پر بغیر سمجھوتے کے واضح موقف دیتی ہے: ‘تمہارے لیے تمہارا دین، میرے لیے میرا دین’ (109:1–6)۔" },
  { n: 110, ad: "Nasr", inis: "Medine", konu: "Zafer geldiğinde: hamd ve istiğfarla veda.", fazilet: "Hz. Peygamber'in veda döneminde çok okuduğu sure; başarıdan sonra hamd ve istiğfar ahlakını öğretir.", aciklama: "Medine'nin son yıllarında inmiştir: 'Yardım ve zafer geldiğinde' insanların grup grup İslam'a girişi bildirilir; ardından 'Rabbine hamd et ve O'ndan bağışlanma dile' çağrısı gelir. İbn Abbâs rivayetine göre Hz. Peygamber bunu okuyunca yolculuğunun sona yaklaştığını anladı. Zaferin sonrası hamd ve istiğfardır — güçlenen mümin, kibirlenmek yerine af diler.", nuzul: "Nasr suresi Medine döneminde nazil olduğu kabul edilir ve genellikle Hz. Peygamber’in vefatına yakın bir döneme işaret ettiği rivayet edilir. Fetih ve insanların gruplar halinde İslam’a girişi müjdelendikten sonra tesbih, hamd ve istiğfar emredilir (110:1-3). Bazı sahabe bu sureyi görevin tamamlanması ve ahirete hazırlık işareti olarak anlamıştır; bu yorum rivayetlerde yer alır.", nuzul_en: "Surah an-Nasr is generally regarded as Madinan and reported to have been revealed near the end of the Prophet’s life. After announcing victory and people entering Islam in groups, it commands glorification, praise, and seeking forgiveness (110:1–3). Some Companions understood it as a sign of completing the mission and preparing for the Hereafter, as reflected in reports.", nuzul_ar: "تُعد سورة النصر مدنية، وتذكر روايات نزولها قرب وفاة النبي. تبشر بالفتح ودخول الناس في الدين أفواجًا ثم تأمر بالتسبيح والحمد والاستغفار (110:1-3). وفهمها بعض الصحابة إشارة إلى اكتمال المهمة.", nuzul_id: "Surah an-Nasr umumnya dipandang Madaniyah dan diriwayatkan turun menjelang wafat Nabi. Setelah kabar kemenangan dan manusia masuk Islam berbondong-bondong, surah ini memerintahkan tasbih, pujian, dan istighfar (110:1–3). Sebagian sahabat memahaminya sebagai tanda selesainya tugas.", nuzul_ur: "سورۃ النصر کو عموماً مدنی مانا جاتا ہے اور روایات میں اسے نبی کی وفات کے قریب قرار دیا جاتا ہے۔ فتح اور لوگوں کے جوق در جوق اسلام میں داخل ہونے کی بشارت کے بعد تسبیح، حمد اور استغفار کا حکم ہے (110:1–3)۔ بعض صحابہ نے اسے ذمہ داری کی تکمیل کی طرف اشارہ سمجھا۔" },
  { n: 112, ad: "İhlâs", inis: "Mekke", konu: "Tevhidin özeti — Allah bir, samed, doğurmadı, doğurulmadı.", fazilet: "Kulun 'Allah'ı bilme' çabasının zirvesi; 'İhlâs, Kur'an'ın üçte birine denk gelir' rivayeti (Tirmizî) ile tevhidin en net beyanı sayılır.", aciklama: "'İhlâs' samimiyet demektir; bütün ibadetin ilkesi buraya sığar. Allah bir, Samed'dir (herkes O'na muhtaç, O kimseye muhtaç değil); doğurmadı ve doğurulmadı; hiçbir şey O'na denk değil. Dört kısa cümle, putperestlikten 'Allah'ın oğlu var' fikrine kadar bütün yanlış tasavvurları tek tek çürütür. Peygamber (s.a.v.) bu surenin sevabının Kur'an'ın üçte birine denk geldiğini bildirmiştir — çünkü tevhid, Kur'an'ın üçte biridir.", nuzul: "İhlâs suresi iniş yeri hakkında Mekke ve Medine rivayetleri vardır. Rivayetlerde müşriklerin veya bazı muhatapların ‘Rabbinin nesebi/sıfatı nedir?’ türü sorularına tevhidi saf haliyle cevap olarak indiği aktarılır; soru sahipleri ve ayrıntılar rivayetlere göre değişebilir. Sure, Allah’ın birliğini, samed oluşunu ve doğurmama/doğmama/benzerinin olmamasını açıkça beyan eder (112:1-4).", nuzul_en: "Surah al-Ikhlas is reported with both Meccan and Medinan attributions. Reports state it answered questions about God’s nature with pure monotheism; details vary. It affirms Allah’s oneness, self-sufficiency, and that He neither begets nor is begotten, and none is comparable to Him (112:1–4).", nuzul_ar: "تُذكر سورة الإخلاص بمكي ومدني. وتنقل روايات أنها جاءت جوابًا عن سؤال في ذات الله ببيان التوحيد الخالص، مع اختلاف في التفاصيل. تقرر أحدية الله والصمدية ونفي الولد والكفء (112:1-4).", nuzul_id: "Surah al-Ikhlas diriwayatkan Mekah dan Madinah. Riwayat menyebutnya sebagai jawaban tauhid murni atas pertanyaan tentang hakikat Allah; rincian berbeda. Ia menegaskan keesaan Allah, tempat bergantung, serta penafian anak, diperanakkan, dan sekutu (112:1–4).", nuzul_ur: "سورۃ الاخلاص کے نزول میں مکی اور مدنی اقوال ہیں۔ روایات میں اسے اللہ کی ذات کے بارے میں سوال کے خالص توحیدی جواب کے طور پر بیان کیا جاتا ہے؛ تفصیلات مختلف ہیں۔ یہ اللہ کی وحدانیت، صمدیت اور اولاد/والد/مثیل کی نفی بیان کرتی ہے (112:1–4)۔" },
  { n: 113, ad: "Felak", inis: "Mekke", konu: "Şerrden sığınma — gece karanlığı, büyü, kıskançlık.", fazilet: "Sabah-akşam üçer kez okunması sünnettir (muavvizât); Peygamber (s.a.v.) hastaların üzerine üfürerek okurdu.", aciklama: "'Felak' sabah yarılması demektir: kötülüğün doğmasından önce gün doğumuna sığınmak gibi. Şerrinden sığınılan üç şey sayılır: karanlık basınca gecenin, düğümlere üfleyenin (büyü ve hurafe) ve kıskandığı zaman kıskananın. İnsanın maddi-manevi bütün tehlikelerine karşı 'Allah'a sığınırım' demenin en kısa yolu.", nuzul: "Felak suresi iniş yeri hakkında Mekke ve Medine rivayetleri bulunur. Muavvizeteyn (Felak ve Nas) ile ilgili rivayetlerde Hz. Peygamber’e zarar vermek amacıyla yapılan büyü/zarar girişimi ve bu surelerin şifa/koruma olarak okunması bağlamı aktarılır (Buhârî ve Müslim’de ilgili rivayetler bulunur; tefsirlerde ayrıntılar tartışılır). Sure, yaratılmışın şerrinden ve özellikle karanlık, düğüm ve haset şerrinden Allah’a sığınmayı öğretir (113:1-5).", nuzul_en: "Surah al-Falaq has Meccan and Medinan attributions. Reports about al-Mu‘awwidhatayn (al-Falaq and an-Nas) mention harm directed at the Prophet and recitation for protection/healing; related narrations appear in hadith collections and are discussed in tafsir. The surah teaches seeking refuge in Allah from created harms, darkness, knots, and envy (113:1–5).", nuzul_ar: "تُذكر سورة الفلق بمكي ومدني. وترد في أحاديث المعوذتين روايات عن أذى قصد به النبي والرقية بهما، مع نقاش في التفاصيل. تعلم السورة الاستعاذة بالله من شر المخلوقات ومن الغاسق والنفاثات والحاسد (113:1-5).", nuzul_id: "Surah al-Falaq memiliki atribusi Mekah dan Madinah. Riwayat tentang Mu‘awwidzatain menyebut gangguan terhadap Nabi dan pembacaan untuk perlindungan; riwayat terkait dibahas dalam hadis dan tafsir. Surah ini mengajarkan berlindung kepada Allah dari kejahatan makhluk, kegelapan, sihir simpul, dan dengki (113:1–5).", nuzul_ur: "سورۃ الفلق کے نزول میں مکی اور مدنی اقوال ہیں۔ معوذتین کی روایات میں نبی کو پہنچائے گئے اذیت اور حفاظت/رقیہ کے طور پر ان کی تلاوت کا ذکر ملتا ہے؛ تفصیلات حدیث و تفسیر میں زیر بحث ہیں۔ سورت مخلوق کے شر، اندھیرے، گرہوں اور حسد سے اللہ کی پناہ سکھاتی ہے (113:1–5)۔" },
  { n: 114, ad: "Nâs", inis: "Mekke", konu: "İnsanların, cinlerin şerrinden Allah'a sığınma.", fazilet: "Vesveseye karşı en güçlü sığınak (muavvizât); uyku öncesi çocuklara üçer kez okutulan gelenek hadislerle desteklenir.", aciklama: "Sığınma serisinin son suresi: insanların Rabbine, Melikine ve İlahına sığınılır — kalpteki vesveseyi ancak Allah'ın üç ismiyle savunabilirsin. Cin ve insan şeytanlarının fısıltısına karşı kapıyı kapatır; göğse değil, kalbe çalışan düşman daha sinsi olduğu için son sıradadır. Muavvizât'ın (sığınma surelerinin) kapanışıdır.", nuzul: "Nâs suresi iniş yeri hakkında Mekke ve Medine rivayetleri vardır ve Felak ile birlikte Muavvizeteyn olarak okunur. Korunma/şifa bağlamındaki rivayetler Felak ile birlikte değerlendirilir. Sure, insanların Rabbi, Meliki ve İlâhı olan Allah’a, vesvese veren şerden (cin ve insan kaynaklı kötülüğe karşı) sığınmayı öğretir (114:1-6). Nüzul mesajı, görünür-görünmez vesveselere karşı tevhidî sığınaktır.", nuzul_en: "Surah an-Nas has Meccan and Madinan attributions and is recited with al-Falaq as al-Mu‘awwidhatayn. Reports of protection/healing are considered alongside al-Falaq. It teaches seeking refuge in Allah, Lord, Sovereign, and God of mankind, from the evil of the whisperer among jinn and humans (114:1–6), grounding protection in tawhid.", nuzul_ar: "تُذكر سورة الناس بمكي ومدني وتُقرأ مع الفلق بوصفهما المعوذتين. تعلم الاستعاذة برب الناس وملكهم وإلههم من شر الوسواس الخناس من الجنة والناس (114:1-6).", nuzul_id: "Surah an-Nas memiliki atribusi Mekah dan Madinah dan dibaca bersama al-Falaq sebagai Mu‘awwidzatain. Ia mengajarkan berlindung kepada Allah, Tuhan, Raja, dan sesembahan manusia, dari kejahatan pembisik dari jin dan manusia (114:1–6).", nuzul_ur: "سورۃ الناس کے نزول میں مکی اور مدنی اقوال ہیں اور اسے فلق کے ساتھ معوذتین کے طور پر پڑھا جاتا ہے۔ یہ لوگوں کے رب، بادشاہ اور معبود کی پناہ، وسوسہ ڈالنے والے جن و انس کے شر سے سکھاتی ہے (114:1–6)۔" }
];

// ★ 114 SURE TAMAMLAMA (02.10, kullanıcı kararı): mevcut 25 meşhur sure
//   kalır; kalan 89 sure kısa konu + fazilet olarak ek dosyadan birleşir.
//   İniş yerleri quran.com chapters API ile doğrulanmıştır.
import { SURE_BİLGİLERİ_EK } from "./sureBilgileriEk";
SURE_BİLGİLERİ.push(...SURE_BİLGİLERİ_EK);
SURE_BİLGİLERİ.sort((a, b) => a.n - b.n);
